import{_ as o,o as c,c as d,a2 as S}from"./chunks/framework.Bg-Zxr5O.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/N-OF-CASES.md","filePath":"manual-zh/N-OF-CASES.md","lastUpdated":1785684581000}'),a={name:"manual-zh/N-OF-CASES.md"};function t(E,e,A,r,n,s){return c(),d("div",null,[...e[0]||(e[0]=[S(`<h3 id="_13-2-n-of-cases" tabindex="-1">13.2 N OF CASES <a class="header-anchor" href="#_13-2-n-of-cases" aria-label="Permalink to &quot;13.2 N OF CASES&quot;">​</a></h3><pre><code>N [OF CASES] num_of_cases [ESTIMATED].
</code></pre><p><code>N OF CASES</code> 限制其之后命令流中任意过程所处理的个案数量。例如，<code>N OF CASES 100</code> 告诉 PSPP 忽略前 100 个之后的所有个案。</p><p>当 <code>N OF CASES</code> 在 <code>TEMPORARY</code> 之后指定时，它只影响下一个过程（参见 <a href="./TEMPORARY">TEMPORARY</a>）。否则，超出指定限制的个案不会被任何后续过程处理。</p><p>如果 <code>N OF CASES</code> 上指定的限制大于活动数据集中的个案数量，则不起作用。</p><p>当 <code>N OF CASES</code> 与 <code>SAMPLE</code> 或 <code>SELECT IF</code> 一起使用时，个案限制应用于抽样或个案选择之后获得的个案，无论 <code>N OF CASES</code> 在命令文件中相对于 <code>SAMPLE</code> 或 <code>SELECT IF</code> 的位置如何。因此，无论它们在命令文件中的顺序如何，<code>N OF CASES 100</code> 和 <code>SAMPLE .5</code> 都会先随机抽取活动数据集大约一半的个案，然后选择这些被抽样个案中的前 100 个。</p><p>带有 <code>ESTIMATED</code> 关键字的 <code>N OF CASES</code> 在 <code>DATA LIST</code> 或另一个读取数据的命令之前给出估计的个案数量。<code>ESTIMATED</code> 从不限制过程所处理的个案数量。PSPP 当前不使用个案计数估计值。</p>`,7)])])}const C=o(a,[["render",t]]);export{p as __pageData,C as default};
